echo "== 9: una clave de API exporta"; annul "$AF" "  if (connection.authType !== 'oauth') throw" "  if (false) throw"
echo "== 10: siempre se refresca"; annul "$AF" "  if (!shouldRefreshAnthropicConnection(connection, now())) return connection" "  void 0"
echo "== 11: el refresco irrecuperable es un fallo genérico"; annul "$AF" "  if (refreshed && 'unrecoverable' in refreshed) {" "  if (false) {"
echo "== 12: el refresco no se persiste"; annul "$AF" "  deps.store.update(connectionId, {" "  void ({"
