echo "== 14: los datos del proveedor se reemplazan"; annul "$AF" "{ ...toRecord(connection.providerSpecificData), ...toRecord(refreshed.providerSpecificData) }" "toRecord(refreshed.providerSpecificData)"
echo "== 15: la caducidad no se recalcula"; annul "$AF" "expiresAt: typeof refreshed.expiresIn === 'number' ? new Date(now() + refreshed.expiresIn * MILLISECONDS_PER_SECOND).toISOString() : connection.expiresAt || null," "expiresAt: connection.expiresAt || null,"
echo "== 16: el archivo por la etiqueta"; annul "$AF" "sanitizeFileNamePart(email || connectionLabel)" "sanitizeFileNamePart(connectionLabel)"
echo "== 17: sin copia al lado"; annul "$AF" "    await copyFile(authPath, savedBakPath)" "    void 0"
echo "== 18: lo demás del archivo se pierde"; annul "$AF" "JSON.stringify({ ...existingDoc, claudeAiOauth:" "JSON.stringify({ claudeAiOauth:"
echo "== 19: legible por todos"; annul "$AF" "const OWNER_ONLY = 0o600" "const OWNER_ONLY = 0o644"
echo "== 20: sin informar lo conservado"; annul "$AF" "mcpOAuthPreserved: !!existingDoc.mcpOAuth" "mcpOAuthPreserved: false"
echo "== 21: se importa sin access token"; annul "$AI" "  if (!accessToken) throw" "  if (false) throw"
echo "== 22: se importa sin refresh token"; annul "$AI" "  if (!refreshToken) throw" "  if (false) throw"
echo "== 23: la caducidad numérica queda en milisegundos"; annul "$AI" "expiresAt = new Date(block.expiresAt).toISOString()" "expiresAt = String(block.expiresAt)"
echo "== 24: la caducidad en texto sin recortar"; annul "$AI" "expiresAt = block.expiresAt.trim()" "expiresAt = block.expiresAt"
echo "== 25: los alcances importados sin filtrar"; annul "$AI" "block.scopes.filter((scope): scope is string => typeof scope === 'string')" "(block.scopes as string[])"
echo "== 26: un bootstrap caído rompe la importación"; annul "$AI" "    if (!response.ok) return base" "    void 0"
echo "== 27: el nivel del archivo se pierde"; annul "$AI" "toNonEmptyString(body.rate_limit_tier) || parsed.rateLimitTier" "toNonEmptyString(body.rate_limit_tier)"
echo "== 28: sin correo del bootstrap"; annul "$AI" "email: parsed.email || toNonEmptyString(body.account_email)," "email: parsed.email,"
echo "== 29: la cuenta distingue mayúsculas"; annul "$AI" "?.toLowerCase() === wanted" " === accountUUID"
echo "== 30: el duplicado se sobrescribe solo"; annul "$AI" "      if (!options.overwriteExisting) {" "      if (false) {"
echo "== 31: la identidad de dispositivo se renueva"; annul "$AI" "cliUserID: toNonEmptyString(existingData.cliUserID) || newDeviceId()" "cliUserID: newDeviceId()"
echo "== 32: el nombre existente se pierde"; annul "$AI" "name: options.name || (existing.name as string | undefined) || options.email" "name: options.name || options.email"
echo "== 33: sin identidad se importa"; annul "$AI" "  if (!enriched.email && !enriched.accountUUID && !options.overwriteExisting) {" "  if (false) {"
echo "== 34: sin nombre por defecto"; annul "$AI" "const IMPORTED_NAME = 'Anthropic (imported)'" "const IMPORTED_NAME = ''"
echo "== 35: un fetch que lanza rompe la importación"; annul "$AI" "  } catch {
    return base
  } finally {" "  } finally {"
echo "== restaurado"; git -C "$T" status --short -- src/packages/provider/src/accounts/imports; run
